def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_x_squared(x):
    factors = prime_factorization(x)
    tau = 1
    for p, e in factors.items():
        # If x = p^e, then x^2 = p^(2e). Tau(x^2) = 2e + 1.
        tau *= (2 * e + 1)
    return tau

# Test candidates (1260, 1680, 720, 840)
candidates = [1260, 1680, 720, 840, 1716, 1620]
results = {}
for x in candidates:
    results[x] = tau_x_squared(x)

